const lerp = (a, b, t) => a + (b - a) * t;   // t 는 0~1

// 진행률 t 를 곡선으로 한 번 통과시키면 느낌이 바뀐다
const easeOut = (t, p = 3) => 1 - Math.pow(1 - t, p);  // 처음 빠르고 끝 느리게
const easeIn  = (t, p = 3) => Math.pow(t, p);           // 처음 느리고 끝 빠르게

// 값이 아니라 진행률 t 를 이징한다
const value = lerp(from, to, easeOut(t));
// 선형(그대로)은 등속이라 기계적·싸구려 — 현실은 가속·감속한다

// ❌ 프레임마다 고정량 → 화면 주사율에 따라 속도가 달라진다
x += 2;

// ✅ 시간 기반 — 경과 시간으로 진행률 t
const start = performance.now();
function frame(now) {
  const t = Math.min(1, (now - start) / duration);   // 0~1
  const eased = easeOut(t);
  el.style.transform = `translateX(${lerp(0, 300, eased)}px)`;
  if (t < 1) requestAnimationFrame(frame);            // t=1 이면 종료
}
requestAnimationFrame(frame);
// CSS transition/animation 은 이미 시간 기반 — JS 직접 애니메이션만 주의

/* 동작 줄이기를 켠 사용자 → 움직임을 즉시 전환으로 */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
/* 정보는 없애지 마라 — 모달은 여전히 나타나되 슬라이드 없이 즉시 */

